"""Curated recs for catalog dests that previously used region fallbacks."""


def rec(hotels, food, acts):
    return {"hotels": hotels, "food": food, "acts": acts}


def H(why_b, b, why_m, m, why_l, l, note, fb, fm, fl, ab, am, al):
    return rec((why_b, b, why_m, m, why_l, l), (note, fb, fm, fl), (ab, am, al))


